function OUT = AF7R58ZZV_ONEFILE_TWO_SPIKE_TARGETED_INSTALL()
% AF7R58ZZV
% Targeted fix for ONLY the two remaining replanner timing regions:
%   A) Flight entry (~5.0 s)
%   B) replanning window (~9.85--10.1 s)
%
% No worker, no parpool, no parfeval, no thread/process offload.
% No warm-up is moved into Arming/Takeoff/Flight/Landing.
%
% A) Flight-entry hot path
%   - full certificate structures are validated pre-Arming;
%   - live Flight uses an exact dependency/version/stale-bit guard;
%   - per-cycle func2str() reconstruction is removed;
%   - exact hot guard + active-reference geometry chain is primed only in
%     framework initialization before real Arming.
%
% B) Replan window
%   - Stage 1 ordinary H=4 s trigger is latched for the 2-cycle pipeline;
%   - raw sensor + sensor-memory freshness still run every cycle;
%   - if known-obstacle mask/dependency/map/version changes, commit is stale;
%   - Stage 2 pre-builds the first repaired future-reference packet;
%   - Stage 3 performs freshness + atomic authority swap + hot guard.
%
% Safety contracts unchanged:
%   H=4 s fixed; immediate ordinary trigger; no extended preview;
%   finite sensing; continuous certificate; unresolved/stale => reject.

PRE_SHA='c5e0753344024fa155a2ffd359b3dacfdc14ad68559df786bf316add9bfa12ba';
POST_SHA='cbc183990c230078d61f01ab5157802036cc20dac6738e1f6465e7a7b212cff3';

OUT=struct('schema','AF7R58ZZV_TWO_SPIKE_TARGETED_INSTALL_V1', ...
    'production_modified',false,'rollback_performed',false, ...
    'pre_sha','','post_sha','','status','OPEN','error',struct());

pR=which('REPLANNING_SYSTEM');
assert(~isempty(pR)&&isfile(pR),'[AF7R58ZZV] REPLANNING_SYSTEM unresolved.');
root=fileparts(pR);

outdir=tempname(root);
[ok,msg]=mkdir(outdir); assert(ok,'%s',msg);
report=fullfile(outdir,'AF7R58ZZV_REPORT.txt');
matp=fullfile(outdir,'AF7R58ZZV_OUT.mat');
backup=fullfile(outdir,'REPLANNING_SYSTEM_PRE_AF7R58ZZV.m');

fid=fopen(report,'wt','n','UTF-8'); assert(fid>=0);
cf=onCleanup(@()safe_fclose(fid)); %#ok<NASGU>

say(fid,'====================================================================================================');
say(fid,' AF7R58ZZV | TWO-SPIKE TARGETED INSTALL');
say(fid,'====================================================================================================');
say(fid,'[SCOPE] FlightEntryOnly=1 | ReplanWindowOnly=1 | HLCChanged=0');
say(fid,'[WORKER] process=0 | thread=0 | parpool=0 | parfeval=0');
say(fid,'[PHASE] preArmInitializationPrime=1 | arming/takeoff/flight/landingWarmup=0');
say(fid,'[TRIGGER] fixedH4s=1 | immediateStage1=1 | pendingKernelRelatch=0');
say(fid,'[FRESHNESS] rawSensorEveryCycle=1 | newKnownObstacleReject=1 | dep/map/versionReject=1');
say(fid,'[CERT] continuousMathChanged=0 | finiteSensingChanged=0');

wrote=false;
try
